# Try filling between ALL pairs of non-zero values in each row
def fill_between_pairs(grid):
    output = [row[:] for row in grid]
    for r in range(len(grid)):
        nz_cols = sorted([c for c in range(len(grid[r])) if grid[r][c] != 0])
        for i in range(len(nz_cols) - 1):
            left = nz_cols[i]
            right = nz_cols[i + 1]
            # Fill between this pair
            for c in range(left + 1, right):
                if output[r][c] == 0:
                    output[r][c] = 2
    return output

test_input = [
    [0, 0, 6, 0, 0, 0, 0, 0, 6],
    [0, 6, 0, 6, 0, 0, 0, 6, 0],
    [6, 0, 0, 0, 6, 0, 6, 0, 0],
    [0, 0, 0, 0, 0, 6, 0, 0, 0]
]

result = fill_between_pairs(test_input)
print("Fill between all pairs in each row:")
for row in result:
    print(row)

# Compare with row-based fill
def row_min_max_fill(grid):
    output = [row[:] for row in grid]
    for r in range(len(grid)):
        nz_cols = [c for c in range(len(grid[r])) if grid[r][c] != 0]
        if len(nz_cols) >= 2:
            for c in range(nz_cols[0] + 1, nz_cols[-1]):
                if output[r][c] == 0:
                    output[r][c] = 2
    return output

result2 = row_min_max_fill(test_input)
print("\nRow min-max fill:")
for row in result2:
    print(row)
